CREATE SCHEMA IF NOT EXISTS aldos;
SET search_path TO aldos,pg_catalog;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN('customer','admin')),phone TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,category_id TEXT NOT NULL REFERENCES categories(id),name TEXT NOT NULL,description TEXT NOT NULL,universe TEXT NOT NULL,price_cents INTEGER NOT NULL CHECK(price_cents>=1),stock INTEGER NOT NULL CHECK(stock>=0),image TEXT NOT NULL,image2 TEXT,tag TEXT NOT NULL,condition TEXT NOT NULL,edition TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS carts(id TEXT PRIMARY KEY,user_id TEXT UNIQUE REFERENCES users(id),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cart_items(cart_id TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99),PRIMARY KEY(cart_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL CHECK(status IN('awaiting_payment','paid','shipped','completed','cancelled')),payment_state TEXT NOT NULL DEFAULT 'new' CHECK(payment_state IN('new','creating','ready','capturing','captured','cancelling','cancelled')),subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents>=0),shipping_cents INTEGER NOT NULL CHECK(shipping_cents>=0),total_cents INTEGER NOT NULL CHECK(total_cents=subtotal_cents+shipping_cents),address_json TEXT NOT NULL,paypal_id TEXT UNIQUE,capture_id TEXT UNIQUE,paypal_create_key TEXT NOT NULL,paypal_capture_key TEXT NOT NULL,checkout_key TEXT NOT NULL UNIQUE,tracking TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,paid_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_order ON orders(user_id) WHERE status='awaiting_payment';
CREATE TABLE IF NOT EXISTS order_items(order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,image TEXT NOT NULL,unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>0),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99),PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS inventory_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),delta INTEGER NOT NULL,reason TEXT NOT NULL,order_id TEXT REFERENCES orders(id),actor_id TEXT REFERENCES users(id),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS custom_requests(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),piece TEXT NOT NULL,category TEXT NOT NULL,budget_cents INTEGER NOT NULL CHECK(budget_cents>0),details TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'received' CHECK(status IN('received','searching','quoted','closed')),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,window_start INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,target TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id,active);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_requests_user ON custom_requests(user_id,created_at);



REVOKE ALL ON SCHEMA aldos FROM PUBLIC;
